0643.\n\u0627\u0631\u0641\u0639 \u062f\u0645\u0628\u0644\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629 \u0648\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0631\u0641\u0639 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0630\u0631\u0627\u0639\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0645\u0639 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0642\u0645 \u0628\u0627\u0644\u062a\u0628\u062f\u064a\u0644 \u0628\u064a\u0646 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0415","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["traps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0415-SxHteRW.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/e