convention":"bodyweight","guidance":{"steps_en":"Stand tall with your feet shoulder-width apart.\nExtend your arms straight out to the sides, parallel to the ground.\nSlowly bring your arms forward, crossing them in front of your body.\nFeel the stretch in your chest muscles.\nHold the stretch for 10-30 seconds.\nReturn to the starting position and repeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0637\u0648\u064a\u0644\u064b\u0627 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646\u060c \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0628\u0628\u0637\u0621\u060c \u0648\u0627\u0639\u0628\u0631\u0647\u0645\u0627 \u0623\u0645\u0627\u0645 \u062c\u0633\u0645\u0643.\n\u0627\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 10-30 \u062b\u0627\u0646\u064a\u0629.\n\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1167","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1167-3uj0Ozg.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1167-3uj0Ozg.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4ee2672a-5898-5f0c-8810-124c2d5860a4","source_id":"3287","name_en":"elbow dips","name_ar":"\u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636\u0627\u062a \u0627\u0644\u0643\u0648\u0639","match_names":["elbow dips"],"muscle":"triceps","equipment":"bodyweight","aliases":["elbow dips"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.\nSlide your hips forward off the bench and straighten your legs, keeping your heels on the ground.\nBend your elbows and lower your body towards the ground, keeping your back close to the bench.\nPause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u0645\u0642\u0639\u062f \u0623\u0648 \u0627\u0644\u0643\u0631\u0633\u064a \u0645\u0639 \u0625\u0645\u0633\u0627\u0643 \u064a\u062f\u064a\u0643 \u0628\u0627\u0644\u062d\u0627\u0641\u0629 \u0628\u062c\u0648\u0627\u0631 \u0648\u0631\u0643\u064a\u0643.\n\u062d\u0631\u0643 \u0648\u0631\u0643\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0642\